import React, { useState, useEffect } from 'react';

function Analytics() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState("ALL");

  useEffect(() => {
    fetch('http://localhost:5000/api/analytics')
      .then(res => res.json())
      .then(d => {
        console.log("API DATA:", d); // 🔍 DEBUG
        setData(d);
        setLoading(false);
      })
      .catch(err => {
        console.error(err);
        setLoading(false);
      });
  }, []);

  if (loading) return <p>Loading...</p>;
  if (!data) return <p style={{ color: 'red' }}>Backend not running</p>;

  // ✅ SAFE FILTER (IMPORTANT FIX)
  const filteredUAVs = (data.uavs || []).filter(u => {
    if (filter === "ALL") return true;
    return u.status === filter;
  });

  return (
    <div>
      <h2>Analytics</h2>

      {/* ✅ KPI CARDS */}
      <div style={{ display: 'flex', gap: '12px', margin: '20px 0' }}>
        {[
          { label: 'Total', value: data.total, color: 'blue', type: 'ALL' },
          { label: 'Passed', value: data.passed, color: 'green', type: 'Passed' },
          { label: 'Failed', value: data.failed, color: 'red', type: 'Failed' },
          { label: 'In Progress', value: data.inProgress, color: 'orange', type: 'In Progress' },
        ].map(k => (
          <div
            key={k.label}
            onClick={() => setFilter(k.type)}
            style={{
              border: `2px solid ${k.color}`,
              padding: '15px',
              borderRadius: '8px',
              cursor: 'pointer',
              background: filter === k.type ? '#e6f0ff' : 'white',
              textAlign: 'center',
              width: '120px'
            }}
          >
            <h2 style={{ color: k.color }}>{k.value}</h2>
            <p>{k.label}</p>
          </div>
        ))}
      </div>

      {/* ✅ DEBUG VIEW (IMPORTANT) */}
      <p><b>Selected Filter:</b> {filter}</p>
      <p><b>Total UAVs:</b> {data.uavs?.length || 0}</p>

      {/* ❌ If no UAVs */}
      {!data.uavs || data.uavs.length === 0 ? (
        <p style={{ color: 'red' }}>No UAV data found</p>
      ) : (
        <>
          {/* ✅ UAV TABLE */}
          <h3>UAV List ({filter})</h3>

          <table border="1" cellPadding="8" style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead style={{ background: '#333', color: 'white' }}>
              <tr>
                <th>UAV ID</th>
                <th>Status</th>
              </tr>
            </thead>

            <tbody>
              {filteredUAVs.length === 0 ? (
                <tr>
                  <td colSpan="2">No UAVs found</td>
                </tr>
              ) : (
                filteredUAVs.map(u => (
                  <tr key={u.id}>
                    <td>{u.id}</td>
                    <td style={{
                      color:
                        u.status === 'Passed' ? 'green' :
                        u.status === 'Failed' ? 'red' :
                        'orange',
                      fontWeight: 'bold'
                    }}>
                      {u.status}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </>
      )}
    </div>
  );
}

export default Analytics;
